	.em_mob_block {
		display: block !important;
	}

	.em_hide {
		display: none !important;
	}

	.em_clear {
		clear: both !important;
		width: 100% !important;
		display: block !important;
	}
	.em_hide_desktop {
		display: table !important;
		float: none !important;
		width: 100% !important;
		overflow: visible !important;
		height: auto !important;
	}
